-- Search: normalization, trigram index, and a generated search column.
--
-- GENERATED BY HAND, but mirrored exactly by `normalizeSearchText()` in
-- lib/algorithms/search.ts. The two implementations are asserted to agree on a
-- table of real spellings in src/test/search.e2e.test.ts; if they drift, that
-- test fails rather than search silently returning different results depending
-- on which path executed.
--
-- Why a function at all: pg_trgm does NOT unify Arabic spellings. Measured on
-- this database, similarity('دراجة هوائية', 'دراجه هوائيه') = 0.53, because
-- trigrams are computed on raw characters. The alef/hamza/taa-marbuta folds must
-- therefore happen BEFORE the index, so the index is over normalized text.
--
-- Why IMMUTABLE: it is required for the expression index below and for use in a
-- GENERATED column. That is only sound because the function reads nothing but
-- its argument and depends on no setting or locale: lower() and regexp_replace()
-- with explicit character classes qualify, whereas anything using collation or
-- search_path would silently be a lie.

--> statement-breakpoint
CREATE EXTENSION IF NOT EXISTS pg_trgm;

--> statement-breakpoint
CREATE OR REPLACE FUNCTION search_normalize(input text) RETURNS text
LANGUAGE plpgsql
IMMUTABLE
PARALLEL SAFE
AS $$
DECLARE
  text_value text;
  digit_index integer;
  arabic_digits text := '٠١٢٣٤٥٦٧٨٩';
  extended_digits text := '۰۱۲۳۴۵۶۷۸۹';
  ascii_digits text := '0123456789';
BEGIN
  IF input IS NULL THEN
    RETURN '';
  END IF;

  -- Compatibility decomposition first, exactly as the JS does: presentation
  -- forms and ligatures (ﻻ) become their letters before any other rule runs.
  -- PostgreSQL 17 provides normalize() with the Unicode forms, which is what
  -- makes this function a mirror rather than an approximation.
  text_value := normalize(input, NFKC);

  text_value := lower(text_value);

  -- Arabic folds happen BEFORE NFD, because NFD decomposes the hamza carriers
  -- and would make these rules look like they work by accident.
  text_value := regexp_replace(text_value, '[\u0610-\u061A\u064B-\u065F\u0670\u06D6-\u06ED]', '', 'g');
  text_value := regexp_replace(text_value, '\u0640', '', 'g');
  text_value := translate(text_value, 'آأإٱ', 'اااا');  -- alef forms -> alef
  text_value := translate(text_value, 'ئ', 'ي');        -- hamza on yaa
  text_value := translate(text_value, 'ؤ', 'و');        -- hamza on waw
  text_value := translate(text_value, 'ى', 'ي');        -- alef maqsura
  text_value := translate(text_value, 'ة', 'ه');        -- taa marbuta

  -- Arabic-Indic digits, mapped one pair at a time.
  FOR digit_index IN 0..9 LOOP
    text_value := replace(text_value, substr(arabic_digits, digit_index + 1, 1), substr(ascii_digits, digit_index + 1, 1));
    text_value := replace(text_value, substr(extended_digits, digit_index + 1, 1), substr(ascii_digits, digit_index + 1, 1));
  END LOOP;

  -- Latin accents last: decompose, then drop only U+0300-036F. The range is
  -- deliberately narrow so that both implementations can state it identically.
  text_value := normalize(text_value, NFD);
  text_value := regexp_replace(text_value, '[\u0300-\u036F]', '', 'g');

  -- Collapse whitespace and trim; same set as the JS `\s+`.
  text_value := regexp_replace(text_value, '\s+', ' ', 'g');
  text_value := btrim(text_value);

  RETURN text_value;
END;
$$;

-- products: keep `name` (what the user sees) and index a normalized column.
ALTER TABLE "products" ADD COLUMN "search_text" text;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION products_search_text_refresh() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  -- The derived column is recomputed only when its sources actually changed.
  -- A WHEN clause cannot express this: triggers with both INSERT and UPDATE
  -- events may not reference OLD, and may not reference TG_OP at all. Guarding
  -- inside the body is the only correct place, and it also protects the column
  -- from being clobbered by an UPDATE that touches unrelated fields.
  IF TG_OP = 'UPDATE'
     AND NEW."name" IS NOT DISTINCT FROM OLD."name"
     AND NEW."code" IS NOT DISTINCT FROM OLD."code" THEN
    RETURN NEW;
  END IF;
  NEW.search_text := search_normalize(coalesce(NEW.name, '') || ' ' || coalesce(NEW.code, ''));
  RETURN NEW;
END;
$$;

--> statement-breakpoint
CREATE TRIGGER "products_search_text_trg"
  BEFORE INSERT OR UPDATE OF "name", "code" ON "products"
  FOR EACH ROW EXECUTE FUNCTION products_search_text_refresh();

--> statement-breakpoint
UPDATE "products" SET "search_text" = search_normalize(coalesce("name", '') || ' ' || coalesce("code", ''));

--> statement-breakpoint
CREATE INDEX "products_search_trgm_idx" ON "products" USING gin ("search_text" gin_trgm_ops);

--> statement-breakpoint
-- clients: name and code, same treatment.
ALTER TABLE "clients" ADD COLUMN "search_text" text;
